        rLocalLHS(1,2)+=-clhs16*clhs27;
        rLocalLHS(1,3)+=-clhs18*clhs27;
        rLocalLHS(1,4)+=-clhs20*clhs27;
        rLocalLHS(1,5)+=-clhs22*clhs27;
        rLocalLHS(1,6)+=-clhs24*clhs27;
        rLocalLHS(1,7)+=-clhs26*clhs27;
        rLocalLHS(2,0)+=-clhs12*clhs28;
        rLocalLHS(2,1)+=-clhs12*clhs29;
        rLocalLHS(2,2)+=-clhs12*clhs30;
        rLocalLHS(2,3)+=-clhs12*clhs31;
        rLocalLHS(2,4)+=-clhs12*clhs32;
        rLocalLHS(2,5)+=-clhs12*clhs33;
        rLocalLHS(2,6)+=-clhs12*clhs34;
        rLocalLHS(2,7)+=-clhs12*clhs35;
        rLocalLHS(3,0)+=-clhs27*clhs28;
        rLocalLHS(3,1)+=-clhs27*clhs29;
        rLocalLHS(3,2)+=-clhs27*clhs30;
        rLocalLHS(3,3)+=-clhs27*clhs31;
        rLocalLHS(3,4)+=-clhs27*clhs32;
        rLocalLHS(3,5)+=-clhs27*clhs33;
        rLocalLHS(3,6)+=-clhs27*clhs34;
        rLocalLHS(3,7)+=-clhs27*clhs35;
        rLocalLHS(4,0)+=clhs12*clhs36;
        rLocalLHS(4,1)+=clhs12*clhs37;
        rLocalLHS(4,2)+=clhs12*clhs38;
        rLocalLHS(4,3)+=clhs12*clhs39;
        rLocalLHS(4,4)+=clhs12*clhs40;
        rLocalLHS(4,5)+=clhs12*clhs41;
        rLocalLHS(4,6)+=clhs12*clhs42;
        rLocalLHS(4,7)+=clhs12*clhs43;
        rLocalLHS(5,0)+=clhs27*clhs36;
        rLocalLHS(5,1)+=clhs27*clhs37;
        rLocalLHS(5,2)+=clhs27*clhs38;
