        const double clhs54 =     DeltaNormalSlave[3](0,0)*clhs7 + DeltaNormalSlave[3](0,1)*clhs15 + DeltaNormalSlave[3](0,2)*clhs23 + NormalSlave(0,0)*(DOperator(0,1) + DeltaDOperator[3](0,0)*clhs0 + DeltaDOperator[3](0,1)*clhs1 + DeltaDOperator[3](0,2)*clhs2 + DeltaDOperator[3](0,3)*clhs3 - DeltaMOperator[3](0,0)*clhs4 - DeltaMOperator[3](0,1)*clhs5 - DeltaMOperator[3](0,2)*clhs6) + NormalSlave(0,1)*(DeltaDOperator[3](0,0)*clhs8 + DeltaDOperator[3](0,1)*clhs9 + DeltaDOperator[3](0,2)*clhs10 + DeltaDOperator[3](0,3)*clhs11 - DeltaMOperator[3](0,0)*clhs12 - DeltaMOperator[3](0,1)*clhs13 - DeltaMOperator[3](0,2)*clhs14) + NormalSlave(0,2)*(DeltaDOperator[3](0,0)*clhs16 + DeltaDOperator[3](0,1)*clhs17 + DeltaDOperator[3](0,2)*clhs18 + DeltaDOperator[3](0,3)*clhs19 - DeltaMOperator[3](0,0)*clhs20 - DeltaMOperator[3](0,1)*clhs21 - DeltaMOperator[3](0,2)*clhs22);
